package com.salespunch360.mobile.account
import kotlinx.serialization.json.*
import org.junit.Assert.*
import org.junit.Test
class ReferenceReportCatalogueTest {
    @Test fun searchesSupportedReferenceAliasesWithoutChangingTheDestination(){val options=Json.parseToJsonElement("""{"catalogue":[{"key":"customer-ledger","name":"Customer Ledger","group":"Parties","aliases":["Party Statement"]}]}""").jsonObject;assertEquals(listOf("customer-ledger"),accountReportCatalogue(options,"Party Statement").map{it.key});assertTrue(accountReportCatalogue(options,"missing").isEmpty())}
    @Test fun unavailableRowsHaveReasonsAndNeverBecomeExecutableReportNames(){val options=Json.parseToJsonElement("""{"reports":["tax"],"unavailableCatalogue":[{"name":"GSTR-3B","group":"GST reports","reason":"Filing generation is not available."}]}""").jsonObject;assertEquals("GSTR-3B",accountUnavailableReportCatalogue(options,"gstr").single().name);assertTrue(accountReportCatalogue(options).none{it.key=="gstr-3b"});assertTrue(accountUnavailableReportCatalogue(options,"stock").isEmpty())}
    @Test fun olderServerWithoutOptionalUnavailableMetadataStillWorks(){val options=Json.parseToJsonElement("""{"reports":["tax"]}""").jsonObject;assertTrue(accountUnavailableReportCatalogue(options).isEmpty());assertEquals("tax",accountReportCatalogue(options).single().key)}
    @Test fun dayBookUsesOneDateForRowsAndExportsAndDropsUnrelatedFilters(){val filters=accountReportRequestFilters(buildJsonObject{},"day-book",mapOf("from" to "2026-04-01","to" to "2026-10-23","branchId" to "branch","customerId" to "customer","accountType" to "BANK"));assertEquals(mapOf("from" to "2026-10-23","to" to "2026-10-23","branchId" to "branch"),filters)}
    @Test fun batchReportRetainsProductAndLiteralSearchWithoutUnrelatedStockFilters(){val options=Json.parseToJsonElement("""{"catalogue":[{"key":"item-batch","filters":["productId","itemSearch"]}]}""").jsonObject;assertEquals(mapOf("productId" to "product","itemSearch" to "%_","to" to "2026-10-13"),accountReportRequestFilters(options,"item-batch",mapOf("productId" to "product","itemSearch" to "%_","to" to "2026-10-13","categoryId" to "category","stockLevel" to "LOW")))}
    @Test fun partyItemReportsRetainOnlyServerAdvertisedFilters(){for(report in listOf("party-items","item-party")){val options=Json.parseToJsonElement("""{"catalogue":[{"key":"$report","filters":["productId","itemSearch","customerId","vendorId"]}]}""").jsonObject;assertEquals(mapOf("productId" to "product","itemSearch" to "%_","customerId" to "customer","vendorId" to "vendor"),accountReportRequestFilters(options,report,mapOf("productId" to "product","itemSearch" to "%_","customerId" to "customer","vendorId" to "vendor","stockLevel" to "LOW","classificationSide" to "SALES")))}}
}
